Translate("ruRU", "dun-morogh", {
	title = "Дун Морог",
	sections = {
		{
			title = "Обзор",
			text = [=[Дун Морог — край снега и камня на западе Каз Модана, древней родины {link:dwarves}дворфов{/link}. Его вершины — самые высокие в {link:eastern-kingdoms}Восточных королевствах{/link}, и в величайшей из них лежит {link:ironforge}Стальгорн{/link}, столица {link:kingdom-of-ironforge}королевства Стальгорн{/link}. Когда-то здесь жили и {link:gnomes}гномы{/link} — в городе {link:gnomeregan}Гномреган{/link} под западными холмами. Между двумя городами лежат замерзшие озера, сосновые леса и единственная длинная дорога через снега. Это суровая страна, и ее народ ею гордится.]=],
		},
		{
			title = "Истоки",
			text = [=[{link:dwarves}Дворфы{/link} говорят, что в минувшие эпохи они были сотворены из камня этих гор и что {link:ironforge}Стальгорн{/link} — их древнейший дом. Давным-давно всеми дворфами правил из него единый верховный король. Когда этот король умер, кланы Бронзобородов, Неистового Молота и Черного Железа начали войну за его трон, и гора осталась за Бронзобородами. {link:gnomes}Гномы{/link} стали соседями и друзьями дворфов и возвели {link:gnomeregan}Гномреган{/link} в западных предгорьях. Ни одна летопись не называет года, когда был основан тот или другой город.]=],
		},
		{
			title = "Наши дни",
			text = [=[Дун Морог менее безопасен, чем когда-либо на памяти живущих. Большая часть королевского войска далеко — служит {link:alliance}Альянсу{/link} в чужих краях, а оставшихся горных пехотинцев мало. {link:troggs}Трогги{/link} хлынули из глубин и теперь удерживают Туннель Холодной долины и ямы Карьера {link:gol-bolar-quarry}Гол'Болар{/link}. {link:frostmane-trolls}Тролли Мерзлогривы{/link} держат свои пещеры и гряды на западе. {link:gnomeregan}Гномреган{/link} потерян, и его отравленные жители бродят перед его воротами. Серую берлогу заполонили вендиго. Тревожнее всего то, что на востоке видели лазутчиков {link:dark-iron-dwarves}клана Черного Железа{/link} с картами туннелей, которые ведут под сам {link:ironforge}Стальгорн{/link}.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:dwarves}Дворфы{/link} {link:ironforge}Стальгорн{/link}а.{/b} Рудокопы, пивовары, заводчики баранов и горные пехотинцы; они живут в {link:kharanos}Каранос{/link}е, в Поселке Пивоваров и в одиноких лагерях высокогорья.
• {b}{link:gnomes}Гномы{/link} {link:gnomeregan}Гномреган{/link}а.{/b} Выжившие жители павшего города нашли приют в Стальгорне, а некоторые трудятся в Караносе, чтобы исправить причиненный вред.
• {b}{link:frostmane-trolls}Тролли Мерзлогривы{/link}.{/b} Они держат пещеры и гряды на западе и оспаривают снега у дворфов.
• {b}{link:troggs}Трогги{/link}.{/b} Трогги {link:stonesplinter-troggs}Камнедробы{/link} поднялись из-под земли и теперь нападают везде, где копают дворфы.
• {b}Вендиго и звери.{/b} Вендиго, медведи, кабаны и снежные барсы бродят по холмам, и некоторые из них стали слишком дерзкими и слишком крупными.
• {b}{link:dark-iron-dwarves}Дворфы Черного Железа{/link}.{/b} Их отряд удерживает Мастерскую {link:prospector-ironband}Сталекрут{/link}а на востоке, наблюдая и выжидая.]=],
		},
		{
			title = "История",
			text = [=[• {b}Три Молота.{/b} В войне трех кланов Бронзобороды удержали {link:ironforge}Стальгорн{/link} и изгнали своих соперников. Договор, хранящийся под городом, свидетельствует, что клан Неистового Молота подписал мир, а {link:dark-iron-dwarves}клан Черного Железа{/link} — нет.
• {b}{link:second-war}Вторая война{/link}.{/b} Когда {link:horde}Орда{/link} наводнила Каз Модан, сам Стальгорн выстоял. {link:dwarves}Дворфы{/link} вступили в {link:alliance}Альянс Лордерона{/link} и сражались бок о бок с людьми, пока Орда не была разбита.
• {b}Падение {link:gnomeregan}Гномреган{/link}а.{/b} {link:troggs}Трогги{/link} поднялись под {link:gnomes}гном{/link}ским городом. Гномы сражались, чтобы изгнать их, но оружие, которое они применили, отравило город и многих из них самих. Выжившие бежали в Стальгорн.
• {b}Наши дни.{/b} Теперь дворфы противостоят троггам, троллям и дворфам Черного Железа разом, а половина их сил далеко, на войне.]=],
		},
		{
			title = "Предания гор",
			text = [=[• Семья Громоваров из {link:kharanos}Каранос{/link}а и семья Ячменеваров из Поселка Пивоваров — соперничающие роды пивоваров. Каждый считает, что эль другого годится только кабанам.
• {link:frostmane-trolls}Тролли Мерзлогривы{/link} выращивают на грядах над Заледеневшим озером бледную траву, которую зовут мерцающей травой, и используют ее в своих ритуалах. {link:dwarves}Дворфы{/link} нашли ей лучшее применение: стаут.
• {link:gorn}Горн{/link}ые пехотинцы {link:ironforge}Стальгорн{/link}а вырезают свои имена на прикладах ружей, чтобы можно было заставить снег сказать, кого он забрал.
• Воры в Стальгорне шепчутся, что бронированные паровые танки короля возят руду и самоцветы из Карьера {link:gol-bolar-quarry}Гол'Болар{/link} странно окольной дорогой и что кому-нибудь стоило бы избавить его от малой их части.]=],
		},
	},
})

Translate("ruRU", "coldridge-valley", {
	title = "Холодная долина",
	sections = {
		{
			title = "Обзор",
			text = [=[Холодная долина — укрытая лощина на юго-западе {link:dun-morogh}Дун Морог{/link}а, со всех сторон замкнутая горами. Новые защитники {link:ironforge}Стальгорн{/link}а приходят сюда учиться своему ремеслу в Старой {link:nak}Нак{/link}овальне. {link:stranglethorn-vale}Долина{/link} утратила покой. {link:troggs}Трогги{/link} {link:stonesplinter-troggs}Камнедробы{/link} захватили лагерь на западе и кишат в холмах у замерзшего озера. {link:frostmane-trolls}Тролли Мерзлогривы{/link} удерживают пещеру на юге. Единственная дорога наружу, через Туннель Холодной долины, теперь полна троггов, и у его входа несет стражу горный пехотинец.]=],
		},
	},
})

Translate("ruRU", "anvilmar", {
	title = "Старая Наковальня",
	sections = {
		{
			title = "Обзор",
			text = [=[Старая {link:nak}Нак{/link}овальня — жилище, глубоко врытое в склон горы в верховье Холодной долины. Здесь наставники {link:ironforge}Стальгорн{/link}а учат молодых сражаться, молиться и заниматься ремеслом, а снабженцы дают им теплую одежду от холода. Это также убежище. {link:gnomes}Гномы{/link}, бежавшие от яда {link:gnomeregan}Гномреган{/link}а, нашли приют в ее залах, и некоторые из них все еще подсчитывают то, что потеряли в дороге.]=],
		},
	},
})

Translate("ruRU", "kharanos", {
	title = "Каранос",
	aliases = { "таверна «Громоварка»" },
	sections = {
		{
			title = "Обзор",
			text = [=[Каранос — главный город {link:dun-morogh}Дун Морог{/link}а, горстка каменных домов на дороге между Холодной долиной и {link:ironforge}Стальгорн{/link}ом. В его сердце стоит таверна «Громоварка», славная на весь Каз Модан, чьи п{link:ogres}огр{/link}еба доверху заставлены бочками Громового эля. В самой таверне редко бывает тихо. Сюда являются с докладом горные пехотинцы, и здесь {link:senir-whitebeard}Сенир Белобород{/link} пишет свои донесения для Сената Стальгорна. Два {link:gnomes}гном{/link}а в городе трудятся над машиной, которая, как они надеются, исцелит их народ.]=],
		},
	},
})

Translate("ruRU", "steelgrill-s-depot", {
	title = "Поселок Сталежара",
	sections = {
		{
			title = "Обзор",
			text = [=[Поселок Сталежара стоит чуть к северо-востоку от {link:kharanos}Каранос{/link}а. Это мастерская, которую держит {link:beldin-steelgrill}Белдин Сталежар{/link}, лучший в горах механик осадных машин, и излюбленное место пилотов Осадной бригады. Их бронированные паровые танки носят имена вроде «Реактивный Пар» и «Троллеплуг», и пилоты хвалятся ими, как другие {link:dwarves}дворф{/link}ы хвалятся баранами. Поселок слышит многое из того, что происходит на дорогах, и именно доклад горного пехотинца здесь впервые привлек внимание к странному костру над {link:gol-bolar-quarry}Гол'Болар{/link}ом.]=],
		},
	},
})

Translate("ruRU", "the-grizzled-den", {
	title = "Серая берлога",
	sections = {
		{
			title = "Обзор",
			text = [=[Серая берлога — пещера в холмах к западу от {link:kharanos}Каранос{/link}а. Ее туннели когда-то были богатым источником руды, и рудокопы Караноса там работали. Потом вендиго расселились из своих пещер и заполонили ее. Рудокопы бежали и бросили свои грузы. {link:gorn}Горн{/link}ый пехотинец Корнелиус вошел внутрь, чтобы узнать, насколько плохи дела, и не вышел. В глубине обитает громогласный и свирепый вендиго по кличке Ледяной Вой.]=],
		},
	},
})

Translate("ruRU", "chill-breeze-valley", {
	title = "Долина Промозглого Ветра",
	sections = {
		{
			title = "Обзор",
			text = [=[Долина Промозглого Ветра открывается на западе {link:dun-morogh}Дун Морог{/link}а, между {link:kharanos}Каранос{/link}ом и холмами {link:gnomeregan}Гномреган{/link}а. Ее восточный отрезок хорошо исхожен, ибо через него идет дорога от Туннеля Холодной долины. В ее более тихие уголки мало кто ходит по своей воле. Там держит пещеру {link:ogres}огр{/link}омный вендиго по кличке Старина Ледобород, и однажды он унес весь ледник с мясом у зверолова Тундры МакГранна, который стоит лагерем неподалеку с больной ногой и пустым животом.]=],
		},
	},
})

Translate("ruRU", "brewnall-village", {
	title = "Поселок Пивоваров",
	sections = {
		{
			title = "Обзор",
			text = [=[Поселок Пивоваров стоит на западном берегу Заледеневшего озера. Это дом семьи Ячменеваров — пивоваров, которые ставят опыты без страха, а порой и без успеха. Их «Вечное сияние» горит так жарко, что пилоты осадных машин заливают его в свои топки. Семья Ячменеваров не питает любви к семье Громоваров из {link:kharanos}Каранос{/link}а и не прочь слегка напроказить в п{link:ogres}огр{/link}ебе своих соперников. Рядом с ними промышляют на озере рыбаки, а с юго-запада наблюдают {link:frostmane-trolls}тролли Мерзлогривы{/link}.]=],
		},
	},
})

Translate("ruRU", "iceflow-lake", {
	title = "Заледеневшее озеро",
	sections = {
		{
			title = "Обзор",
			text = [=[Заледеневшее озеро раскинулось на севере {link:dun-morogh}Дун Морог{/link}а, к западу от {link:ironforge}Стальгорн{/link}а, и большую часть года оно сковано льдом. К нему от моста к северу от {link:kharanos}Каранос{/link}а спускается ледяная река. На острове в его середине охотятся волки. Рыбаки Поселка Пивоваров прорубают лунки во льду и целыми днями ждут над своими лесками, проклиная вендиго, которые воруют их скудный улов.]=],
		},
	},
})

Translate("ruRU", "frostmane-hold", {
	title = "Форт Мерзлогривов",
	sections = {
		{
			title = "Обзор",
			text = [=[Форт Мерзлогривов — {link:ogres}огр{/link}омная пещера троллей Мерзлогривов к юго-западу от Поселка Пивоваров. Охотники за головами, живодеры, снежные бегуны и заклинатели теней обитают там в таком числе, что оно напугало даже {link:dwarves}дворф{/link}а, посланного их пересчитать. Форт — сердце могущества Мерзлогривов в {link:dun-morogh}Дун Морог{/link}е. Что тролли замышляют внутри, дворфы пытались узнать, и их донесения наделали в Сенате не меньше шума, чем в снегах.]=],
		},
	},
})

Translate("ruRU", "shimmer-ridge", {
	title = "Мерцающий хребет",
	sections = {
		{
			title = "Обзор",
			text = [=[Мерцающий хребет — гряда высоких холмов на севере {link:dun-morogh}Дун Морог{/link}а, близ Заледеневшего озера и к западу от Врат {link:ironforge}Стальгорн{/link}а. {link:frostmane-trolls}Тролли Мерзлогривы{/link} держат на нем стоянки, соединенные мостом, и их провидцы ухаживают там за корзинами с мерцающей травой. Эта трава играет какую-то роль в их обрядах. Для пивоваров Поселка Пивоваров у нее другое назначение, и они хорошо платят всякому, кто взберется на хребет, чтобы ее украсть.]=],
		},
	},
})

Translate("ruRU", "gates-of-gnomeregan", {
	title = "Врата Гномрегана",
	sections = {
		{
			title = "Обзор",
			text = [=[К северу от Поселка Пивоваров холмы западного {link:dun-morogh}Дун Морог{/link}а поднимаются к воротам {link:gnomeregan}Гномрегана{/link}. Некогда это был оживленный край {link:gnomes}гном{/link}ских машин и деревень. Теперь насосы и фильтры стоят сломанные, а оставшиеся гномы отравлены, больны и враждебны и бродят перед дверями города, который они не смогли спасти. Среди них под чужой личиной прячется {link:dwarves}дворф{/link}-лазутчик с темными целями. Бежавшие гномы говорят, что драгоценные записи их народа все еще лежат здесь, п{link:ogres}огр{/link}ебенные в снегу.]=],
		},
	},
})

Translate("ruRU", "gol-bolar-quarry", {
	title = "Карьер Гол'Болар",
	aliases = { "Гол'Болар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Карьер Гол'Болар — {link:ogres}огр{/link}омная открытая яма на востоке {link:dun-morogh}Дун Морог{/link}а, где королевские рудокопы добывают руду и камень. Когда они копнули глубоко, {link:troggs}трогг{/link}и {link:stonesplinter-troggs}Камнедробы{/link} хлынули из скалы, разбили машины и выгнали рудокопов из ямы. Теперь десятник бушует, сенатор {link:ironforge}Стальгорн{/link}а платит за головы троггов, а начальник карьера надеется, что никто не узнает, что трогги унесли его взрывной порох. С Холмов Тандрид наверху за всем этим наблюдает чужак из клана Неистового Молота.]=],
		},
	},
})

Translate("ruRU", "amberstill-ranch", {
	title = "Ферма Янтарленов",
	sections = {
		{
			title = "Обзор",
			text = [=[Ферма Янтарленов лежит у дороги к востоку от {link:kharanos}Каранос{/link}а. Семья Янтарленов разводит {link:ogres}огр{/link}омных горных баранов, которые возят {link:dwarves}дворф{/link}ов {link:ironforge}Стальгорн{/link}а, и ее стада — гордость {link:dun-morogh}Дун Морог{/link}а. Бараны с фермы теперь отправляются к экспедиции в {link:alterac-mountains}Альтерак{/link}е, и им нужны седла из лучших шкур барсов. У стада появился и свой охотник: зверь по кличке {link:vagash}Вагаш{/link}, который устроил логово на склонах выше и спускается по ночам.]=],
		},
	},
})

Translate("ruRU", "misty-pine-refuge", {
	title = "Сторожка у заснеженной сосны",
	sections = {
		{
			title = "Обзор",
			text = [=[Сторожка у заснеженной сосны — одинокий дом в северных холмах {link:dun-morogh}Дун Морог{/link}а, к востоку от Врат {link:ironforge}Стальгорн{/link}а. {link:father-gavin}Отец Гэвин{/link} из {link:argent-dawn}Серебряного Рассвета{/link} починил его и поддерживает огонь в очаге для любого путника, застигнутого холодом. Горы вокруг стали опасны. Камнепад с вершин растревожил духов льда, и самый большой из них, кажется, приносит бури и новые обвалы всюду, куда идет.]=],
		},
	},
})

Translate("ruRU", "helm-s-bed-lake", {
	title = "Озеро Хельмово Ложе",
	sections = {
		{
			title = "Обзор",
			text = [=[Озеро Хельмово Ложе лежит на дальнем юго-востоке {link:dun-morogh}Дун Морог{/link}а, близ перевалов в {link:loch-modan}Лок Модан{/link}. Его вода большей частью замерзла, а край вокруг дик и пуст. По его берегам бродят {link:troggs}трогг{/link}и {link:stonesplinter-troggs}Камнедробы{/link}. В холмах к северу пилот осадной машины ждет у двух машин друга, который в одиночку ушел дальше на поиски редкой руды. Этим другом был Мори Хилдельв, и {link:ogres}огр{/link}омный медведь по кличке Шелудивый Коготь нашел его первым.]=],
		},
	},
})

Translate("ruRU", "ironband-s-compound", {
	title = "Мастерская Сталекрута",
	sections = {
		{
			title = "Обзор",
			text = [=[Мастерская Сталекрута — дом и двор к югу от Озера Хельмово Ложе, на востоке {link:dun-morogh}Дун Морог{/link}а. Его хозяева-{link:dwarves}дворф{/link}ы покинули его. Теперь его удерживают дворфы Черного Железа под началом капитана Белда, и они нападают на всякого, кто подойдет близко. {link:earthseer-farsen}Провидец земли Фарсен{/link} из клана Неистового Молота считает, что это не простые налетчики. Карты, снятые с их мертвецов, показывают туннели, которые уходят далеко под землю и сходятся под {link:ironforge}Стальгорн{/link}ом.]=],
		},
	},
})

Translate("ruRU", "frostmane-trolls", {
	title = "Тролли Мерзлогривы",
	aliases = { "Мерзлогривы", "тролли Мерзлогривы", "племя Мерзлогривов" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мерзлогривы — племя {link:trolls}троллей{/link}, живущее в снегах {link:dun-morogh}Дун Морог{/link}а. Они свирепы и скрытны и оспаривают эти горы у {link:dwarves}дворф{/link}ов. Ни одна летопись не сообщает, когда они впервые пришли сюда.]=],
		},
		{
			title = "Их земли",
			text = [=[Их величайший оплот — {link:frostmane-hold}Форт Мерзлогривов{/link}, пещера к юго-западу от Поселка Пивоваров. Они также держат стоянки на Мерцающем хребте и пещеру на юге Холодной долины, где обитает молодняк племени. Их воины — охотники за головами и снежные бегуны. Их провидцы и заклинатели теней творят собственную магию и собирают мерцающую траву для своих ритуалов.]=],
		},
		{
			title = "В наши дни",
			text = [=[У Сената {link:ironforge}Стальгорн{/link}а полно забот с {link:troggs}трогг{/link}ами, и о троллях он предпочел бы не думать вовсе. Двух братьев из семьи Белобородов послали узнать, насколько велика угроза на самом деле. {link:grelin-whitebeard}Грелин{/link} рассудил, что троллей в Холодной долине мало. {link:senir-whitebeard}Сенир{/link} нашел {link:frostmane-hold}Форт Мерзлогривов{/link} полным троллей. Между двумя донесениями лежит вопрос о том, сколь многим {link:dwarves}дворф{/link}ы могут позволить себе пренебречь. В Холодной долине тролль {link:grik-nir-the-cold}Грик'нир Холодный{/link} украл у дворфов больше, чем журнал: он показал им, что Мерзлогривы наблюдают.]=],
		},
	},
})

Translate("ruRU", "gnomeregan-exiles", {
	title = "Изгнанники Гномрегана",
	aliases = { "изгнанники из Гномрегана" },
	sections = {
		{
			title = "Обзор",
			text = [=[Изгнанники Гномрегана — {link:gnomes}гном{/link}ы, пережившие падение своего города. Это народ без дома. Большинство из них живет в {link:ironforge}Стальгорне{/link}, где король {link:magni-bronzebeard}Магни Бронзобород{/link} дал им место в Городе Механиков, но они рассеяны по всему {link:dun-morogh}Дун Морог{/link}у и за его пределами.]=],
		},
		{
			title = "После падения",
			text = [=[{link:troggs}Трогги{/link} поднялись под {link:gnomeregan}Гномреган{/link}ом, и {link:gnomes}гном{/link}ы отбросили их оружием собственного изготовления. Все пошло чудовищно не так. Город был отравлен, а многие его жители превратились в больных и безумных зараженных, которые до сих пор бродят перед его воротами. Остальные бежали в снега с тем, что смогли унести. Некоторые по пути потеряли все из-за троллей. Другие оставили позади записи о своих семьях, своих изобретениях и своем ремесле.]=],
		},
		{
			title = "В наши дни",
			text = [=[Изгнанники не сдались. В {link:kharanos}Каранос{/link}е {link:razzle-sprysprocket}Раззл Шустрошестер{/link} и Оззи Тумблервольт строят машину, которая, как они надеются, исцелит отравленных {link:gnomes}гном{/link}ов. В {link:ironforge}Стальгорн{/link}е механики {link:gnomeregan}Гномреган{/link}а посылают отважных чужаков обратно в город — спасать его утраченные знания. Главный механик {link:gelbin-mekkatorque}Гелбин Меггакрут{/link} клянется, что его народ отвоюет свой дом у предателя, который его удерживает.]=],
		},
	},
})

Translate("ruRU", "sten-stoutarm", {
